-- Raghdan location backfill from LIVE SOURCE PAGE evidence (2026-08-09).
-- ROOT CAUSE: raghdan serves two page shapes. On the REGA-sourced shape the JSON-LD `address`
-- carries only {"addressCountry":"SA"} while the page BODY renders the full «الموقع» card
-- (المنطقة / المدينة / الحى / الرمز البريدي). The scraper read JSON-LD only, so 172 of raghdan's
-- 361 live rows stored city/region/neighborhood = NULL and were unreachable by EVERY city filter
-- (48.5% production-ready, worst in the fleet). A CAPTURE gap, never missing source data.
-- Fixed forward in scrapers/raghdan/run.py:_rendered_location(); this backfills rows already stored.
-- EVIDENCE: all 172 pages re-fetched live 2026-08-09 and parsed with that SAME function (no second
-- divergent parser), then mapped through the unchanged normalize.map_city / REGION_AR path.
-- 168 yielded a full city+region+district; the raw Arabic the page printed is stored alongside each
-- row so any value can be re-checked against the source. NOTHING IS INFERRED — the 4 rows that
-- yielded no catalog city are deliberately ABSENT: 597998 «العويقيلة» (real town, not in the city
-- catalog), 1034250 «حقروصين» (village), 598213 + 2032198 HTTP 404 (dead, left to liveness/prune).
-- Region -> City -> District architecture untouched; only per-listing values move.
CREATE TABLE IF NOT EXISTS public.ops_raghdan_location_backfill_20260809 (
  listing_id bigint PRIMARY KEY, old_city text, old_region text, old_neighborhood text,
  new_city text NOT NULL, new_region text, new_neighborhood text, new_postal text,
  src_city_ar text, src_region_ar text, backed_up_at timestamptz NOT NULL DEFAULT now());

INSERT INTO public.ops_raghdan_location_backfill_20260809
  (listing_id, old_city, old_region, old_neighborhood, new_city, new_region, new_neighborhood,
   new_postal, src_city_ar, src_region_ar)
