egion, nb, postal, cty_ar, rgn_ar)
JOIN public.raghdan_residential_listings l ON l.id = v.id
ON CONFLICT (listing_id) DO NOTHING;

UPDATE public.raghdan_residential_listings l
SET city = b.new_city,
    region = b.new_region,
    neighborhood = coalesce(l.neighborhood, b.new_neighborhood),
    zip_code = coalesce(l.zip_code, b.new_postal),
    additional_info = coalesce(l.additional_info, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
        'city_ar', b.src_city_ar, 'region_ar', b.src_region_ar,
        'district_ar', b.new_neighborhood, 'postal_code', b.new_postal))
FROM public.ops_raghdan_location_backfill_20260809 b
WHERE l.id = b.listing_id AND l.city IS NULL;
